#!/usr/bin/env bash
# ============================================================================
# 3Rivers mobile API — one-shot deploy. Run on onshore01 (10.0.0.71) as root:
#     bash /root/deploy-3rivers-mobile.sh
# Safe to re-run. Backups: *.bak-mobilev1-<timestamp>
# After this, create the Keycloak client `3rivers-mobile` (realm onshoretech,
# public, Direct access grants ON) and run the verify curls printed at the end.
# ============================================================================
set -euo pipefail
APP=/opt/3rivers/app
NGINX=/etc/nginx/conf.d/3rivers.onshoretech.ai.conf
TS=$(date +%Y%m%d-%H%M%S)

echo "== 1/7  write mobile_v1.py =="
base64 -d > "$APP/mobile_v1.py" <<'MV1_B64'

MV1_B64
chown three_rivers:three_rivers "$APP/mobile_v1.py"
"$APP/venv/bin/python" -c "import ast; ast.parse(open('$APP/mobile_v1.py').read()); print('  syntax OK')"

echo "== 2/7  venv deps =="
if "$APP/venv/bin/python" -c "import jwt, cryptography" 2>/dev/null; then
  echo "  PyJWT + cryptography present"
else
  "$APP/venv/bin/pip" install --quiet "PyJWT[crypto]" && echo "  installed PyJWT[crypto]"
fi

echo "== 3/7  wire router into main.py =="
if grep -q mobile_v1_router "$APP/main.py"; then
  echo "  already wired"
else
  cp "$APP/main.py" "$APP/main.py.bak-mobilev1-$TS"
  {
    printf '\n\n# --- mobile app API (own JWT bearer verify, NOT behind oauth2-proxy) ---\n'
    printf 'from mobile_v1 import router as mobile_v1_router  # noqa: E402\n'
    printf 'app.include_router(mobile_v1_router)\n'
  } >> "$APP/main.py"
  echo "  appended (backup: main.py.bak-mobilev1-$TS)"
fi

echo "== 4/7  nginx: add /api/v1/ bypass (skips oauth2-proxy) =="
if grep -q 'location \^~ /api/v1/' "$NGINX"; then
  echo "  already present"
else
  cp "$NGINX" "$NGINX.bak-mobilev1-$TS"
  awk '
    /^[[:space:]]*location \/api\/ \{/ && !done {
      print "  location ^~ /api/v1/ {"
      print "    proxy_pass http://127.0.0.1:9000;"
      print "    proxy_http_version 1.1;"
      print "    proxy_set_header Host              $host;"
      print "    proxy_set_header X-Real-IP         $remote_addr;"
      print "    proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;"
      print "    proxy_set_header X-Forwarded-Proto $scheme;"
      print "    proxy_read_timeout 60;"
      print "  }"
      print ""
      done=1
    }
    { print }
  ' "$NGINX.bak-mobilev1-$TS" > "$NGINX"
  echo "  inserted (backup: $NGINX.bak-mobilev1-$TS)"
fi

echo "== 5/7  nginx test + reload =="
nginx -t
systemctl reload nginx

echo "== 6/7  restart 3rivers-api =="
systemctl restart 3rivers-api
sleep 2
echo "  active: $(systemctl is-active 3rivers-api)"
journalctl -u 3rivers-api -n 20 --no-pager | tail -20

echo "== 7/7  smoke test =="
code=$(curl -s -o /dev/null -w '%{http_code}' https://3rivers.onshoretech.ai/api/v1/dashboard)
echo "  no-auth /api/v1/dashboard -> $code  (want 401; 302 = nginx bypass not active)"

cat <<'NEXT'

============================================================================
NEXT: create Keycloak client `3rivers-mobile` (realm onshoretech, public,
Direct access grants ON), then verify with a real 3Rivers staff account:

  TOK=$(curl -s -d 'grant_type=password&client_id=3rivers-mobile&username=USER&password=PASS&scope=openid' \
    https://auth.onshoresystems.ai/realms/onshoretech/protocol/openid-connect/token \
    | python3 -c 'import sys,json;print(json.load(sys.stdin)["access_token"])')

  curl -s https://3rivers.onshoretech.ai/api/v1/me          -H "Authorization: Bearer $TOK"
  curl -s https://3rivers.onshoretech.ai/api/v1/dashboard   -H "Authorization: Bearer $TOK"
  curl -s https://3rivers.onshoretech.ai/api/v1/work-orders -H "Authorization: Bearer $TOK" | head -c 400
============================================================================
NEXT
